sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float level;
uniform float softness;
uniform float source;
uniform float dither;
layout(color) uniform half4 darkColor;
layout(color) uniform half4 lightColor;
uniform float invert;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float v = source < 0.5 ? luma(s) : (source < 1.5 ? s.r : (source < 2.5 ? s.g : s.b));
    v += (hash21(coord) - 0.5) * dither * 0.25;
    float k = smoothstep(level - softness, level + softness + 0.0001, v);
    if (invert > 0.5) k = 1.0 - k;
    float3 o = mix(float3(darkColor.rgb), float3(lightColor.rgb), k);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
